/* Gate for the baked 13 px text cell (fonts/wubu_font_text.h).
 *
 * The cell is generated by tools/font_bake.py from third_party/fonts/selawik.ttf with a DejaVu
 * fallback. Generation is where holes are possible: a face with no outline for a codepoint, a
 * fallback that does not resolve, a table that stops short of LAST. None of that fails a compile,
 * and none of it is visible until a string draws a box on screen -- so the facts that make the
 * table usable are asserted here instead.
 *
 * The byte pin is deliberate: any rebake changes it, and a human must look at the new table and
 * update the number. A silent restyle is exactly what this project cannot afford again.
 */
#include <stdio.h>
#include <stdint.h>

#include "fonts/wubu_font_text.h"

static int g_pass, g_fail;

static void ok(int cond, const char *what)
{
    if (cond) {
        g_pass++;
    } else {
        g_fail++;
        printf("  FAIL %s\n", what);
    }
}

static int is_blankable(int cp)
{
    /* Space, no-break space, soft hyphen and the C0/C1 controls are legitimately empty: no face
     * renders a control code, and the baker refuses to invent coverage for them. */
    return cp == ' ' || cp == 0x00A0 || cp == 0x00AD ||
           cp < 0x20 || (cp >= 0x7F && cp <= 0x9F);
}

int main(void)
{
    const int n = (int)(sizeof(g_font_glyphs) / sizeof(g_font_glyphs[0]));
    const int want = WUBU_FONT_TEXT_LAST - WUBU_FONT_TEXT_FIRST + 1;

    ok(n == want, "the table covers every codepoint from FIRST to LAST");

    int bytes = 0, blank = 0, holes = 0, bad_box = 0;
    for (int i = 0; i < n; i++) {
        const WubuGlyphAA *g = &g_font_glyphs[i];
        const int cp = WUBU_FONT_TEXT_FIRST + i;
        if (!g->cov) {
            blank++;
            if (!is_blankable(cp)) holes++;
            if (g->w != 0) bad_box++;
            continue;
        }
        if (g->w <= 0 || g->h <= 0) { bad_box++; continue; }
        bytes += (int)g->w * (int)g->h;
    }

    ok(holes == 0, "no printable codepoint is a hole");
    ok(bad_box == 0, "a blank entry has zero width and a covered entry has a real box");
    ok(bytes == 12385, "coverage bytes match the pinned bake (12385)");

    /* Text layout divides its space using these, so an inconsistent triple silently clips the last
     * line of every panel instead of failing. */
    ok(WUBU_FONT_TEXT_ASCENT + WUBU_FONT_TEXT_DESCENT == WUBU_FONT_TEXT_LINE_H,
       "ascent + descent equals the line height");

    /* The two glyphs the product shows constantly, with their real ink boxes: if the bake silently
     * fell back for ASCII, these are what would change first. */
    const WubuGlyphAA *cap_A = &g_font_glyphs['A' - WUBU_FONT_TEXT_FIRST];
    const WubuGlyphAA *lower_a = &g_font_glyphs['a' - WUBU_FONT_TEXT_FIRST];
    ok(cap_A->cov && cap_A->w >= 7 && cap_A->h >= 8, "'A' has a real ink box");
    ok(lower_a->cov && lower_a->w >= 5, "'a' has a real ink box");

    printf("wubu_font_text: %d passed, %d failed (%d glyphs, %d blanks, %d coverage bytes)\n",
           g_pass, g_fail, n, blank, bytes);
    return g_fail ? 1 : 0;
}
